"""Archive one independently accepted episode after agent inspection of actual images."""
import argparse,json,time,hashlib,shutil
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument("--task",required=True);p.add_argument("--variant",required=True);p.add_argument("--episode",type=Path,required=True);p.add_argument("--baseline",required=True);p.add_argument("--neutral",required=True);p.add_argument("--config",type=Path,required=True);p.add_argument("--manifest",type=Path,required=True);p.add_argument("--strict",type=Path,required=True);p.add_argument("--pairs",type=Path,required=True);p.add_argument("--sheet",required=True);p.add_argument("--visual-note",required=True);p.add_argument("--checkpoint",required=True);a=p.parse_args();ep=a.episode
gates={n:json.loads((ep/n).read_text())[k] for n,k in [("task_review_audit.json","passed"),("task_validation_full.json","accepted"),("source_contact_audit.json","passed"),("self_collision_audit.json","passed")]};assert all(gates.values());assert json.loads((ep/"result.json").read_text())["accepted"];av=json.loads((ep/"avoidance_audit.json").read_text());assert av["accepted"];pair=json.loads(a.pairs.read_text());assert pair["fixed_endpoint_rerouting_supported"];strict=json.loads(a.strict.read_text());assert strict["complete"] and strict["manifest_sha256"]==hashlib.sha256(a.manifest.read_bytes()).hexdigest();row=next(x for x in strict["candidates"] if x["variant"]==a.variant);assert row["static_rejections_absent"] and row["config_sha256"]==hashlib.sha256(a.config.read_bytes()).hexdigest()
D=Path("docs/extensions/doors/lwx_scene_approved_20261026");cp=D/("checkpoint"+a.checkpoint);cp.mkdir();review={"reviewer":"agent","user_approval":False,"time_unix":time.time(),"contact_sheet":a.sheet,"scene_and_avoidance":a.visual_note,"scope":"Sampled actual synchronized video inspection; safety and causality independently checked","tcp_max_deviation_m":av["path_comparison"]["tcp_max_deviation_m"]};record={"recorded_unix":time.time(),"variant":a.task+" "+a.variant,"status":"Independent and paired validation passed; agent actual sampled visual review passed; user review pending","episode":str(ep),"baseline":a.baseline,"neutral":a.neutral,"config":str(a.config),"strict_static_report":str(a.strict),"paired_report":str(a.pairs),"all_seed_fixed_target_necessity":True,"independent_gates":gates,"actual_avoidance":True,"path_comparison":av["path_comparison"],"agent_visual_review":review,"evidence_sha256":{}}
for n in ["metadata.json","result.json","task_review_audit.json","task_validation_full.json","source_contact_audit.json","self_collision_audit.json","avoidance_audit.json"]:
 record["evidence_sha256"][n]=hashlib.sha256((ep/n).read_bytes()).hexdigest()
 if (ep/n).stat().st_size<2000000:shutil.copyfile(ep/n,cp/n)
for src in [a.manifest,a.strict]:shutil.copyfile(src,cp/src.name)
(cp/"agent_actual_visual_review.json").write_text(json.dumps(review,indent=2));(D/("ACCEPTANCE_CHECKPOINT"+a.checkpoint+".json")).write_text(json.dumps(record,indent=2));print(json.dumps(record,indent=2))
